def q(s): return json.dumps(s, ensure_ascii=False)
used=set(l.strip() for l in open(sys.argv[1]) if l.strip())
miss=used-set(S); 
if miss: print("MISSING",miss)
out=["// Otomatik üretildi (tools/gen_strings.py). Anahtar: Türkçe metin.","enum Strings {","    static let table: [String: [String: String]] = ["]
for k,(en,ru,az) in sorted(S.items()):
    out.append(f"        {q(k)}: [\"en\": {q(en)}, \"ru\": {q(ru)}, \"az\": {q(az)}],")
out+=["    ]","}",""]
open(sys.argv[2],"w").write("\n".join(out))
